// Published service worker: pre-caches the app shell so GitDiary keeps working
// offline, matching the "Offline-first / Local-first" design principles.
//
// - The assets manifest is generated by the Blazor SDK at publish time
//   (see <ServiceWorkerAssetsManifest> in GitDiary.Client.csproj).
// - Cross-origin requests (notably api.github.com) are never intercepted so
//   sync/write calls flow through as usual and DiaryStore keeps its normal
//   online/offline semantics via IndexedDB.

self.importScripts('./service-worker-assets.js');

self.addEventListener('install', event => event.waitUntil(onInstall(event)));
self.addEventListener('activate', event => event.waitUntil(onActivate(event)));
self.addEventListener('fetch', event => event.respondWith(onFetch(event)));

const cacheNamePrefix = 'gitdiary-cache-';
const cacheName = `${cacheNamePrefix}${self.assetsManifest.version}`;

const offlineAssetsInclude = [
    /\.dll$/, /\.pdb$/, /\.wasm/, /\.html/, /\.js$/, /\.json$/,
    /\.css$/, /\.woff/, /\.svg/, /\.png/, /\.jpe?g/, /\.gif/, /\.ico/,
    /\.webmanifest$/
];
const offlineAssetsExclude = [
    /^service-worker\.js$/
];

// SPA entry point — served as a fallback for navigation requests when offline.
const offlineNavigationFallback = 'index.html';

async function onInstall() {
    // Fetch and cache all matching items from the manifest.
    //
    // We deliberately do NOT use cache.addAll: it has all-or-nothing semantics,
    // so a single asset returning a 404 (or a hash mismatch triggering an
    // integrity failure) aborts the entire install and leaves the user with
    // *no* offline cache at all. Instead, walk the list with Promise.allSettled
    // and add successful responses individually — any failures are logged but
    // do not prevent the rest of the shell from being cached.
    const assetsRequests = self.assetsManifest.assets
        .filter(asset => offlineAssetsInclude.some(pattern => pattern.test(asset.url)))
        .filter(asset => !offlineAssetsExclude.some(pattern => pattern.test(asset.url)))
        .map(asset => new Request(asset.url, { integrity: asset.hash, cache: 'no-cache' }));

    const cache = await caches.open(cacheName);
    const results = await Promise.allSettled(assetsRequests.map(async req => {
        const response = await fetch(req);
        if (!response || !response.ok) {
            throw new Error(`Failed to fetch ${req.url}: ${response && response.status}`);
        }
        await cache.put(req, response);
    }));

    const failed = results.filter(r => r.status === 'rejected');
    if (failed.length > 0) {
        // Surface partial-install visibility for anyone opening DevTools.
        console.warn(`[GitDiary SW] ${failed.length}/${results.length} assets failed to precache`, failed);
    }
}

async function onActivate() {
    // Drop caches from previous versions.
    const cacheKeys = await caches.keys();
    await Promise.all(cacheKeys
        .filter(key => key.startsWith(cacheNamePrefix) && key !== cacheName)
        .map(key => caches.delete(key)));
}

async function onFetch(event) {
    const request = event.request;

    // Only handle same-origin GETs. Cross-origin (api.github.com etc.) and
    // non-GET requests always go straight to the network so the diary sync
    // pipeline is never masked by cached responses.
    const url = new URL(request.url);
    if (request.method !== 'GET' || url.origin !== self.location.origin) {
        return fetch(request);
    }

    // Skip Blazor hot-reload and framework negotiation endpoints — caching
    // them would break dev-time reconnects if a published SW ever lingered.
    if (url.pathname.includes('/_framework/blazor-hotreload')
        || url.pathname.includes('/_blazor')) {
        return fetch(request);
    }

    // Navigation requests get the SPA shell as an offline fallback.
    const shouldServeIndexHtml = request.mode === 'navigate';
    const cache = await caches.open(cacheName);
    const cachedResponse = shouldServeIndexHtml
        ? await cache.match(offlineNavigationFallback)
        : await cache.match(request);

    return cachedResponse || fetch(request);
}
